     "time": "09-22 20:29",
     "ts": 1790080183,
     "summary": "长春高新(000661.SZ)公告称，公司子公司百克生物近日收到国家药监局下发的重组人源抗呼吸道合胞病毒单克隆抗体注射液组合制剂临床试验申请《受理通知书》。该产品用于预防新生儿和婴幼儿RSV引起的下呼吸道感染，为鸡尾酒组合制剂，相比国内已获批的4款单价产品具有更强中和活性。公告提示，该项目后续进展存在不确定性，对近期业绩不会产生重大影响。 （文章来源：财联社）",
